from components.mutation_membership.work import compute


class TestMutationMembership(unittest.TestCase):
    def test_no_mutation_events(self):
        payload = {"events": [{"time": 0, "op": "refresh"}]}
        self.assertEqual(compute(payload), {})

    def test_start_finish_ordering(self):
        payload = {"events": [
            {"time": 0, "op": "start", "id": "m1"},
            {"time": 1, "op": "start", "id": "m2"},
            {"time": 2, "op": "finish", "id": "m1"},
            {"time": 3, "op": "finish", "id": "m2"},
        ]}
        self.assertEqual(compute(payload), {
            "0": ["m1"],
            "1": ["m1", "m2"],
            "2": ["m2"],
            "3": [],
        })

    def test_finish_unknown_id_ignored(self):
        payload = {"events": [
            {"time": 0, "op": "finish", "id": "ghost"},
            {"time": 1, "op": "start", "id": "m1"},
        ]}
        self.assertEqual(compute(payload), {
            "0": [],
            "1": ["m1"],
        })


if __name__ == "__main__":
    unittest.main()

