class TestResponseDeadlines(unittest.TestCase):
    def test_success_is_null(self):
        payload = {"events": [
            {"time": 0, "op": "refresh"},
            {"time": 1, "op": "response", "id": "fetch-1", "items": ["a"]},
        ]}
        self.assertEqual(compute(payload), {"1": None})

    def test_failure_precedence_over_stale(self):
        payload = {"events": [
            {"time": 5, "op": "response", "id": "fetch-1", "failed": True, "stale": 1},
        ]}
        self.assertEqual(compute(payload), {"0": ["failure", 2005]})

    def test_stale_delay(self):
        payload = {"events": [
            {"time": 10, "op": "response", "id": "fetch-1", "stale": 1},
        ]}
        self.assertEqual(compute(payload), {"0": ["stale", 1010]})

    def test_failure_delay(self):
        payload = {"events": [
            {"time": 10, "op": "response", "id": "fetch-1", "failed": True},
        ]}
        self.assertEqual(compute(payload), {"0": ["failure", 2010]})

    def test_non_response_events_ignored(self):
        payload = {"events": [
            {"time": 0, "op": "start", "id": "m1"},
            {"time": 1, "op": "finish", "id": "m1"},
        ]}
        self.assertEqual(compute(payload), {})


if __name__ == "__main__":
    unittest.main()

