    result = {}
    for i, ev in enumerate(events):
        op = ev.get("op")
        if op == "start":
            mid = ev.get("id")
            if mid not in active:
                active.append(mid)
            result[str(i)] = list(active)
        elif op == "finish":
            mid = ev.get("id")
            if mid in active:
